sys_script_client.script:
function onSubmit() {
   //Type appropriate comment here, and begin script below

   var canSubmit = true;
   var ga = new GlideAjax('x_1305322_learns_0.LearnSphereUtils');
   ga.addParam('sysparm_name', 'refDuplicateSchedule');
   ga.addParam('sysparm_course', g_form.getValue('course'));
   ga.addParam('sysparm_date', g_form.getValue('date'));
   ga.getXML(duplicate);

	g_form.addInfoMessage(canSubmit);
	return canSubmit;

   function duplicate(response) {
		var	result = response.responseXML.documentElement.getAttribute('answer');
		if (result == 'false') {
			canSubmit = false;
			g_form.addErrorMessage('This schedule already exist!');
		}
   }
}
